-- Deepens Libras, Ethnic-Racial Relations, Diversity and Human Rights study materials.
-- Materials remain draft until editorial review/publication.

with v(discipline,topic,position,content) as (
values
('Libras e Educação de Surdos','Língua, linguagem e Libras',1,'Libras é uma língua de modalidade visuoespacial, com estrutura própria. Diferenciar língua de linguagem é importante: linguagem é a capacidade humana de significar e comunicar, enquanto uma língua é um sistema socialmente compartilhado, com regras e formas de uso.'),
('Libras e Educação de Surdos','Língua, linguagem e Libras',2,'Reconhecer Libras como língua impede tratá-la como simples conjunto de gestos ou como tradução literal do português. A língua possui organização gramatical e participa da construção de relações, conhecimentos e identidades de seus usuários.'),
('Libras e Educação de Surdos','Língua, linguagem e Libras',3,'Na formação pedagógica, o estudo de Libras se relaciona à comunicação, ao currículo e à acessibilidade. O futuro pedagogo precisa compreender que barreiras linguísticas podem limitar participação e aprendizagem quando a escola não oferece condições comunicacionais adequadas.'),
('Libras e Educação de Surdos','Língua, linguagem e Libras',4,'Uma atividade oral pode apresentar uma barreira para um estudante surdo quando todas as instruções dependem de escuta. A mesma proposta pode ser reorganizada com Libras, recursos visuais e outros apoios que tornem a informação acessível.'),
('Libras e Educação de Surdos','Língua, linguagem e Libras',5,'Ao analisar uma situação, pergunte qual língua está sendo usada para ensinar, interagir e avaliar. Depois verifique se o estudante tem acesso efetivo a essa língua e aos conceitos trabalhados.'),
('Libras e Educação de Surdos','Língua, linguagem e Libras',6,'Um erro comum é considerar Libras um português sinalizado. Isso apaga suas características linguísticas e pode levar a estratégias pedagógicas inadequadas para estudantes que utilizam Libras como língua de referência.'),
('Libras e Educação de Surdos','Língua, linguagem e Libras',7,'A legislação brasileira reconhece Libras como meio legal de comunicação e expressão e regulamenta sua presença em políticas educacionais e de formação. Na prática, a organização escolar deve considerar as normas vigentes e os recursos disponíveis.'),
('Libras e Educação de Surdos','Língua, linguagem e Libras',8,'Para planejar uma aula acessível, articule a língua de instrução com recursos visuais, exemplos, registros escritos e oportunidades de interação. O apoio linguístico precisa estar integrado ao conteúdo, e não separado dele.'),
('Libras e Educação de Surdos','Língua, linguagem e Libras',9,'Libras é uma língua e deve ser tratada como elemento de acesso ao conhecimento, comunicação e participação. A acessibilidade linguística é parte do trabalho pedagógico com estudantes surdos.'),
('Libras e Educação de Surdos','Língua, linguagem e Libras',10,'Revise diferenciando língua e linguagem e explique por que Libras não deve ser entendida como simples gesto. Depois indique uma barreira linguística possível em uma aula e uma forma de enfrentá-la.'),
('Libras e Educação de Surdos','Cultura e identidade surda',1,'Cultura surda envolve experiências, formas de interação, práticas linguísticas e referências compartilhadas por comunidades surdas. Estudá-la ajuda a compreender que surdez não pode ser analisada somente por uma perspectiva biomédica ou de déficit.'),
('Libras e Educação de Surdos','Cultura e identidade surda',2,'Identidade surda pode ser construída em relação à língua, à comunidade, às experiências sociais e às formas de pertencimento. Não existe uma única trajetória de identidade, por isso o pedagogo deve evitar generalizações sobre todas as pessoas surdas.'),
('Libras e Educação de Surdos','Cultura e identidade surda',3,'Na escola, reconhecer cultura e identidade favorece relações mais respeitosas e amplia a qualidade da comunicação. Também ajuda a evitar expectativas baseadas na ideia de que o estudante surdo precisa simplesmente se adequar às formas ouvintes de interação.'),
('Libras e Educação de Surdos','Cultura e identidade surda',4,'Uma escola pode organizar encontros em que estudantes tenham acesso a narrativas, produções culturais e experiências da comunidade surda. O objetivo é ampliar repertórios e legitimar a diversidade linguística e cultural.'),
('Libras e Educação de Surdos','Cultura e identidade surda',5,'Ao planejar uma atividade, pergunte quais referências culturais aparecem e se estudantes surdos podem participar como sujeitos da experiência, e não apenas como destinatários de uma adaptação.'),
('Libras e Educação de Surdos','Cultura e identidade surda',6,'Um erro comum é usar a expressão “cultura surda” como se todos os surdos compartilhassem exatamente as mesmas práticas. Cultura é dinâmica e atravessada por histórias, famílias, territórios e outras dimensões sociais.'),
('Libras e Educação de Surdos','Cultura e identidade surda',7,'A educação de surdos precisa considerar língua e cultura em conjunto. Isso não significa ignorar o ensino de português escrito, mas reconhecer a importância de condições linguísticas adequadas para ampliar o acesso aos demais conhecimentos escolares.'),
('Libras e Educação de Surdos','Cultura e identidade surda',8,'Na prática pedagógica, inclua fontes produzidas por pessoas surdas, situações de interação em Libras e formas visuais de apresentação quando pertinentes. Isso amplia representação e reduz uma abordagem centrada apenas no olhar de pessoas ouvintes.'),
('Libras e Educação de Surdos','Cultura e identidade surda',9,'Reconhecer cultura e identidade surda significa compreender estudantes surdos como sujeitos sociais e linguísticos. Essa perspectiva contribui para combater práticas de infantilização, isolamento e invisibilização.'),
('Libras e Educação de Surdos','Cultura e identidade surda',10,'Revise explicando como língua, cultura e identidade se relacionam. Depois analise uma prática escolar e indique uma mudança que amplie a presença das experiências surdas no currículo.'),
('Libras e Educação de Surdos','Educação bilíngue de surdos',1,'Educação bilíngue de surdos organiza o ensino considerando duas línguas e seus diferentes papéis. Em propostas bilíngues, Libras ocupa posição central como língua de instrução e interação, enquanto o português pode ser desenvolvido principalmente em sua modalidade escrita.'),
('Libras e Educação de Surdos','Educação bilíngue de surdos',2,'Bilinguismo não significa ensinar duas línguas da mesma maneira ou em horários desconectados. A organização pedagógica precisa considerar como cada língua dá acesso a conhecimentos, interações e práticas de letramento.'),
('Libras e Educação de Surdos','Educação bilíngue de surdos',3,'Para o pedagogo, educação bilíngue exige planejamento linguístico, materiais acessíveis, profissionais preparados e estratégias que permitam participação efetiva. A proposta não deve reduzir o estudante a atividades paralelas por causa da diferença linguística.'),
('Libras e Educação de Surdos','Educação bilíngue de surdos',4,'Uma sequência pode apresentar um conceito em Libras, explorar imagens e exemplos, registrar termos em português escrito e retomar o conhecimento em Libras. As línguas cumprem funções complementares no acesso ao conteúdo.'),
('Libras e Educação de Surdos','Educação bilíngue de surdos',5,'Ao planejar, explicite qual língua será usada em cada parte da atividade, como os estudantes terão acesso às explicações e como poderão demonstrar aprendizagem.'),
('Libras e Educação de Surdos','Educação bilíngue de surdos',6,'Um erro comum é chamar qualquer uso ocasional de sinais de educação bilíngue. Uma proposta bilíngue envolve organização linguística sistemática, currículo, mediação e profissionais capazes de garantir acesso às línguas previstas.'),
('Libras e Educação de Surdos','Educação bilíngue de surdos',7,'A legislação e as políticas educacionais brasileiras reconhecem modalidades e direitos linguísticos específicos para a comunidade surda. A implementação concreta varia conforme sistemas e instituições, por isso o profissional deve consultar normas vigentes.'),
('Libras e Educação de Surdos','Educação bilíngue de surdos',8,'Na avaliação, considere como o estudante terá acesso às instruções e como poderá expressar sua compreensão. Recursos visuais, Libras e registros escritos podem ser combinados conforme o objetivo avaliado.'),
('Libras e Educação de Surdos','Educação bilíngue de surdos',9,'Educação bilíngue busca garantir acesso linguístico e curricular. A língua não é um detalhe metodológico: ela condiciona a possibilidade de participar, compreender e produzir conhecimento.'),
('Libras e Educação de Surdos','Educação bilíngue de surdos',10,'Revise explicando por que uma proposta com alguns sinais não é necessariamente bilíngue. Depois monte a estrutura linguística básica de uma atividade para estudantes surdos.'),
('Libras e Educação de Surdos','Práticas pedagógicas e acessibilidade comunicacional',1,'Acessibilidade comunicacional significa garantir que informações, instruções, interações e avaliações possam ser compreendidas e produzidas pelo estudante. Com estudantes surdos, isso exige atenção especial à língua de instrução e às condições visuais da comunicação.'),
('Libras e Educação de Surdos','Práticas pedagógicas e acessibilidade comunicacional',2,'Materiais visuais, vídeos com recursos acessíveis, organização espacial adequada e mediação em Libras podem reduzir barreiras. A escolha depende do contexto, do objetivo e das formas de comunicação utilizadas pelo estudante.'),
('Libras e Educação de Surdos','Práticas pedagógicas e acessibilidade comunicacional',3,'O pedagogo precisa considerar comunicação já no planejamento. Uma aula não se torna acessível apenas porque possui slides; é necessário verificar se explicações, exemplos, perguntas e respostas estão disponíveis em linguagem que o estudante compreende.'),
('Libras e Educação de Surdos','Práticas pedagógicas e acessibilidade comunicacional',4,'Em uma atividade em grupo, organize o espaço para facilitar o campo visual, combine regras de turno e mantenha instruções acessíveis. Pequenas mudanças na interação podem ampliar muito a participação.'),
('Libras e Educação de Surdos','Práticas pedagógicas e acessibilidade comunicacional',5,'Observe onde a comunicação se interrompe: instrução, debate, material, avaliação ou transição. Essa localização ajuda a escolher o apoio mais pertinente.'),
('Libras e Educação de Surdos','Práticas pedagógicas e acessibilidade comunicacional',6,'Um erro comum é entregar ao estudante surdo o mesmo material usado para ouvintes e considerar que um intérprete resolve todas as barreiras. A acessibilidade também depende de materiais, ritmo, visibilidade e organização pedagógica.'),
('Libras e Educação de Surdos','Práticas pedagógicas e acessibilidade comunicacional',7,'Recursos de acessibilidade devem estar integrados ao ensino. Vídeos, por exemplo, precisam considerar recursos linguísticos e visuais adequados ao público, conforme as possibilidades e normas da instituição.'),
('Libras e Educação de Surdos','Práticas pedagógicas e acessibilidade comunicacional',8,'Na avaliação, disponibilize instruções claras e verifique se a forma de resposta não introduz uma barreira que não tem relação com o conhecimento que está sendo avaliado.'),
('Libras e Educação de Surdos','Práticas pedagógicas e acessibilidade comunicacional',9,'Acessibilidade comunicacional é condição de participação. Quando a informação não chega ao estudante ou não pode ser respondida de modo acessível, a avaliação da aprendizagem fica comprometida.'),
('Libras e Educação de Surdos','Práticas pedagógicas e acessibilidade comunicacional',10,'Revise identificando três pontos de uma aula que podem criar barreiras comunicacionais. Depois explique como reorganizaria esses pontos para estudantes surdos.'),
('Libras e Educação de Surdos','Escola e direitos linguísticos',1,'Direitos linguísticos dizem respeito às condições para usar e desenvolver uma língua em espaços sociais e educacionais. Na escola, isso se relaciona diretamente ao acesso ao currículo, à comunicação e à participação.'),
('Libras e Educação de Surdos','Escola e direitos linguísticos',2,'Reconhecer direitos linguísticos não significa excluir o ensino de outras línguas. Significa organizar a escolarização de modo que a diferença linguística não se transforme em impedimento para aprender e participar.'),
('Libras e Educação de Surdos','Escola e direitos linguísticos',3,'O pedagogo deve conhecer as normas aplicáveis e compreender as responsabilidades da instituição, dos professores e dos profissionais de apoio. A garantia de direitos precisa aparecer na organização cotidiana, não apenas em documentos.'),
('Libras e Educação de Surdos','Escola e direitos linguísticos',4,'Quando uma escola prevê intérprete, materiais visuais e comunicação em Libras, esses recursos precisam estar presentes também em reuniões, avaliações e projetos relevantes para a participação do estudante.'),
('Libras e Educação de Surdos','Escola e direitos linguísticos',5,'Ao avaliar a escola, pergunte: qual é a língua de instrução, quem garante comunicação, como os materiais são acessibilizados e como o estudante participa das decisões e atividades?'),
('Libras e Educação de Surdos','Escola e direitos linguísticos',6,'Um erro comum é entender direito linguístico apenas como oferta de um serviço pontual. A experiência escolar é contínua; por isso, acessibilidade linguística precisa acompanhar o conjunto das situações educativas.'),
('Libras e Educação de Surdos','Escola e direitos linguísticos',7,'O Decreto nº 5.626/2005 regulamentou a Libras e estabeleceu disposições relacionadas à formação e à educação. Normas posteriores também podem alterar ou complementar a organização dos serviços; por isso, consulte sempre a legislação vigente.'),
('Libras e Educação de Surdos','Escola e direitos linguísticos',8,'Na prática, registre falhas de acessibilidade comunicacional e encaminhe as demandas pelos canais institucionais adequados. A atuação pedagógica inclui identificar barreiras e acompanhar se foram resolvidas.'),
('Libras e Educação de Surdos','Escola e direitos linguísticos',9,'Direito linguístico, acessibilidade e aprendizagem estão conectados. Garantir comunicação é parte das condições de uma escolarização que respeite a dignidade e a participação dos estudantes surdos.'),
('Libras e Educação de Surdos','Escola e direitos linguísticos',10,'Revise explicando o que é um direito linguístico no contexto escolar. Depois analise uma situação em que a falta de acessibilidade comunicacional compromete a aprendizagem.'),
('Educação das Relações Étnico-Raciais','Racismo, relações raciais e educação',1,'Relações étnico-raciais dizem respeito às formas históricas e sociais pelas quais grupos são identificados, valorizados, discriminados e representados. Na educação, estudar racismo exige observar currículo, relações, materiais, expectativas e oportunidades.'),
('Educação das Relações Étnico-Raciais','Racismo, relações raciais e educação',2,'Racismo não se resume a uma ofensa individual. Ele também pode aparecer em práticas e estruturas que produzem tratamento desigual, invisibilidade ou desvalorização de determinados grupos. A análise pedagógica precisa considerar dimensões individuais, institucionais e históricas.'),
('Educação das Relações Étnico-Raciais','Racismo, relações raciais e educação',3,'O pedagogo tem responsabilidade na seleção de materiais, mediação de conflitos e organização de experiências que combatam discriminação. A educação antirracista é um trabalho contínuo, não uma atividade isolada em datas comemorativas.'),
('Educação das Relações Étnico-Raciais','Racismo, relações raciais e educação',4,'Uma biblioteca escolar pode ter muitos livros, mas poucos protagonistas negros ou indígenas. Analisar essa distribuição de representação revela uma dimensão curricular que uma atividade pontual sobre racismo não resolve sozinha.'),
('Educação das Relações Étnico-Raciais','Racismo, relações raciais e educação',5,'Ao analisar uma prática, observe quem fala, quem aparece como autor, quais imagens são usadas, quais conflitos são tratados e quais expectativas recaem sobre os estudantes.'),
('Educação das Relações Étnico-Raciais','Racismo, relações raciais e educação',6,'Um erro comum é reduzir relações raciais a “respeitar diferenças” sem discutir desigualdade, poder, história e representação. Uma abordagem consistente combina convivência respeitosa com conhecimento histórico e análise crítica.'),
('Educação das Relações Étnico-Raciais','Racismo, relações raciais e educação',7,'A legislação brasileira determina a inclusão da história e cultura afro-brasileira e africana no currículo da Educação Básica, e as Diretrizes de 2004 orientam a educação das relações étnico-raciais. A implementação exige planejamento curricular contínuo.'),
('Educação das Relações Étnico-Raciais','Racismo, relações raciais e educação',8,'Na prática pedagógica, escolha fontes produzidas por diferentes sujeitos, problematize estereótipos e acompanhe como os estudantes utilizam conceitos raciais e históricos. O trabalho precisa evitar tanto silenciamento quanto exposição estereotipada.'),
('Educação das Relações Étnico-Raciais','Racismo, relações raciais e educação',9,'Educação antirracista envolve currículo, relações e gestão do cotidiano. O objetivo é ampliar reconhecimento, conhecimento e equidade, enfrentando situações discriminatórias e também desigualdades produzidas pelas próprias práticas escolares.'),
('Educação das Relações Étnico-Raciais','Racismo, relações raciais e educação',10,'Revise diferenciando preconceito, discriminação e racismo e explique por que a escola precisa olhar para currículo e práticas, não apenas para conflitos explícitos.'),
('Educação das Relações Étnico-Raciais','História e cultura africana',1,'Estudar história e culturas africanas significa superar uma visão que reduz o continente à escravidão, pobreza ou conflito. A África possui sociedades, formas políticas, sistemas econômicos, conhecimentos e tradições diversas, que precisam ser contextualizados historicamente.'),
('Educação das Relações Étnico-Raciais','História e cultura africana',2,'A diversidade africana impede generalizações como “o povo africano”. Existem diferentes regiões, povos, línguas, religiões e processos históricos. O trabalho pedagógico deve situar temporal e geograficamente os conhecimentos apresentados.'),
('Educação das Relações Étnico-Raciais','História e cultura africana',3,'Na formação do pedagogo, conhecer a história africana amplia a capacidade de selecionar fontes e corrigir representações simplificadas. Também contribui para compreender processos que atravessaram a história brasileira.'),
('Educação das Relações Étnico-Raciais','História e cultura africana',4,'Ao estudar reinos e sociedades africanas, uma turma pode comparar organização política, produção material, comércio e conhecimentos com outras sociedades do mesmo período. A comparação evita apresentar a África como ausência de história.'),
('Educação das Relações Étnico-Raciais','História e cultura africana',5,'Ao escolher um material, confira autoria, recorte temporal, localização, vocabulário e fontes utilizadas. Pergunte também quais aspectos foram omitidos e se a narrativa reproduz estereótipos.'),
('Educação das Relações Étnico-Raciais','História e cultura africana',6,'Um erro comum é tratar África como unidade cultural homogênea. Outro é apresentar apenas conteúdos ligados à escravização, sem estudar sociedades e produções africanas em outros contextos históricos.'),
('Educação das Relações Étnico-Raciais','História e cultura africana',7,'A educação das relações étnico-raciais inclui conhecimentos sobre história e cultura africanas porque esses saberes ajudam a combater representações raciais hierarquizadas. A legislação curricular brasileira dá suporte a essa abordagem.'),
('Educação das Relações Étnico-Raciais','História e cultura africana',8,'Na prática, combine mapas, fontes históricas, produções intelectuais e manifestações culturais contextualizadas. Evite usar símbolos ou objetos apenas como decoração sem explicar sua origem e significado no contexto estudado.'),
('Educação das Relações Étnico-Raciais','História e cultura africana',9,'Conhecer história africana amplia o currículo e desloca uma visão centrada apenas em referências europeias. O cuidado central é preservar diversidade, contexto histórico e autoria das fontes.'),
('Educação das Relações Étnico-Raciais','História e cultura africana',10,'Revise escolhendo uma sociedade africana de um período específico e indicando localização, organização social e uma produção cultural ou científica. Explique por que o recorte evita generalizações.'),
('Educação das Relações Étnico-Raciais','História e cultura afro-brasileira',1,'Cultura afro-brasileira resulta de processos históricos de criação, reelaboração e circulação de saberes por populações negras no Brasil. Ela está presente em linguagens, religiosidades, artes, alimentação, música, organização comunitária e diferentes formas de produção cultural.'),
('Educação das Relações Étnico-Raciais','História e cultura afro-brasileira',2,'Estudar cultura afro-brasileira exige reconhecer protagonismo e diversidade. Não se trata de apresentar uma lista de “contribuições” isoladas, mas de compreender sujeitos históricos, conflitos, permanências e transformações.'),
('Educação das Relações Étnico-Raciais','História e cultura afro-brasileira',3,'No currículo escolar, a abordagem precisa estar conectada a diferentes áreas do conhecimento e não ficar restrita a novembro. A formação do pedagogo inclui capacidade de integrar esse conteúdo de forma sistemática.'),
('Educação das Relações Étnico-Raciais','História e cultura afro-brasileira',4,'Uma turma pode estudar um gênero musical brasileiro analisando origem, circulação, relações de poder e transformações históricas. A proposta trata cultura como processo social, e não apenas como produto folclórico.'),
('Educação das Relações Étnico-Raciais','História e cultura afro-brasileira',5,'Ao planejar uma sequência, identifique qual conceito histórico será aprendido, quais sujeitos aparecem como protagonistas e quais fontes sustentam a narrativa.'),
('Educação das Relações Étnico-Raciais','História e cultura afro-brasileira',6,'Um erro comum é folclorizar a cultura afro-brasileira, reduzindo-a a culinária, dança ou festa sem abordar história, conflitos, produção intelectual e experiências contemporâneas.'),
('Educação das Relações Étnico-Raciais','História e cultura afro-brasileira',7,'A Lei nº 10.639/2003 tornou obrigatório o ensino de história e cultura afro-brasileira e africana na Educação Básica. As diretrizes nacionais posteriores detalharam princípios e orientações para sua implementação.'),
('Educação das Relações Étnico-Raciais','História e cultura afro-brasileira',8,'Na prática, diversifique autores, artistas, cientistas e fontes e conecte conteúdos históricos a questões do presente sem apagar as especificidades de cada período.'),
('Educação das Relações Étnico-Raciais','História e cultura afro-brasileira',9,'Ensinar história e cultura afro-brasileira exige sair da posição de “tema extra” e incorporá-la ao currículo como conhecimento relevante para compreender a formação histórica e cultural do país.'),
('Educação das Relações Étnico-Raciais','História e cultura afro-brasileira',10,'Revise explicando por que cultura afro-brasileira não deve ser tratada apenas como folclore. Depois descreva uma atividade curricular em que esse conteúdo apareça como conhecimento central.'),
('Educação das Relações Étnico-Raciais','Currículo e educação antirracista',1,'Currículo antirracista analisa o que é ensinado, quem é representado, quais conhecimentos são valorizados e como as relações em sala são organizadas. Não basta acrescentar um conteúdo; é necessário observar a estrutura do currículo e do cotidiano.'),
('Educação das Relações Étnico-Raciais','Currículo e educação antirracista',2,'Representatividade envolve presença qualificada e contextualizada de diferentes sujeitos e perspectivas. Um currículo pode incluir autores negros e ainda reproduzir hierarquias se esses autores forem tratados como exceções sem continuidade.'),
('Educação das Relações Étnico-Raciais','Currículo e educação antirracista',3,'O pedagogo pode revisar bibliografias, imagens, exemplos, avaliações e projetos para identificar ausências e estereótipos. A revisão deve ser feita com critérios claros e conhecimento das diretrizes educacionais.'),
('Educação das Relações Étnico-Raciais','Currículo e educação antirracista',4,'Em um projeto interdisciplinar sobre cidade, a turma pode estudar trajetórias de diferentes grupos, analisar dados de desigualdade e produzir narrativas com fontes diversas. Assim, relações raciais entram no conhecimento e não apenas na convivência.'),
('Educação das Relações Étnico-Raciais','Currículo e educação antirracista',5,'Ao revisar um currículo, pergunte quais autores aparecem, quais imagens são recorrentes, quais conceitos são usados e em que momentos a experiência de grupos negros é tratada.'),
('Educação das Relações Étnico-Raciais','Currículo e educação antirracista',6,'Um erro comum é considerar que retirar uma imagem estereotipada já torna o currículo antirracista. Combater desigualdades requer também ampliar conhecimentos, representação, participação e formas de tratar conflitos.'),
('Educação das Relações Étnico-Raciais','Currículo e educação antirracista',7,'As Diretrizes Curriculares Nacionais para Educação das Relações Étnico-Raciais orientam que o tema esteja presente na organização curricular e no cotidiano escolar. A concretização depende de planejamento institucional e formação dos profissionais.'),
('Educação das Relações Étnico-Raciais','Currículo e educação antirracista',8,'Na prática, estabeleça critérios para seleção de materiais: diversidade de autoria, contextualização histórica, qualidade das fontes e ausência de estereótipos. Depois acompanhe como a turma interpreta os conteúdos.'),
('Educação das Relações Étnico-Raciais','Currículo e educação antirracista',9,'Currículo antirracista é uma construção contínua. Ele envolve conhecimento histórico, representação, combate à discriminação e análise das próprias práticas escolares.'),
('Educação das Relações Étnico-Raciais','Currículo e educação antirracista',10,'Revise listando três perguntas que você faria ao auditar um currículo sob a perspectiva das relações étnico-raciais. Depois explique por que cada pergunta é pedagogicamente relevante.'),
('Educação das Relações Étnico-Raciais','Práticas pedagógicas e equidade racial',1,'Práticas pedagógicas com equidade racial combinam expectativas de aprendizagem, combate à discriminação e acesso qualificado ao conhecimento. A escola precisa intervir quando práticas ou relações produzem exclusão, em vez de tratar o problema como assunto exclusivamente familiar.'),
('Educação das Relações Étnico-Raciais','Práticas pedagógicas e equidade racial',2,'Equidade não significa oferecer exatamente a mesma resposta em qualquer situação. Significa considerar desigualdades e barreiras para garantir condições justas de participação e aprendizagem, sem reduzir estudantes às categorias raciais.'),
('Educação das Relações Étnico-Raciais','Práticas pedagógicas e equidade racial',3,'O pedagogo deve acompanhar não apenas conflitos explícitos, mas também distribuição de fala, expectativas, feedback, participação em liderança e acesso a oportunidades. Esses indicadores ajudam a perceber desigualdades cotidianas.'),
('Educação das Relações Étnico-Raciais','Práticas pedagógicas e equidade racial',4,'Em um trabalho em grupo, o professor pode observar quem assume funções de liderança, quem é interrompido e quem recebe as tarefas menos valorizadas. A partir das evidências, pode reorganizar os papéis e discutir regras de participação.'),
('Educação das Relações Étnico-Raciais','Práticas pedagógicas e equidade racial',5,'Ao avaliar uma intervenção, compare a situação antes e depois: participação, qualidade das interações, acesso às fontes e aprendizagem. Assim, a equidade deixa de ser apenas uma intenção declarada.'),
('Educação das Relações Étnico-Raciais','Práticas pedagógicas e equidade racial',6,'Um erro comum é responder a situações racistas apenas com uma advertência individual, sem trabalhar conhecimento, relações e cultura institucional. Intervenções disciplinares podem ser necessárias, mas não substituem o trabalho pedagógico.'),
('Educação das Relações Étnico-Raciais','Práticas pedagógicas e equidade racial',7,'A educação antirracista precisa integrar currículo, formação de profissionais e gestão do cotidiano. As normas nacionais orientam essa responsabilidade e reconhecem a escola como espaço de construção de relações sociais mais equitativas.'),
('Educação das Relações Étnico-Raciais','Práticas pedagógicas e equidade racial',8,'Registre episódios, decisões e resultados com cuidado. Evite expor estudantes e preserve informações sensíveis; o objetivo do registro é melhorar a prática e orientar ações institucionais.'),
('Educação das Relações Étnico-Raciais','Práticas pedagógicas e equidade racial',9,'Equidade racial é construída por decisões concretas: quem participa, o que aprende, quais referências encontra e como a escola reage à discriminação. O trabalho é pedagógico e institucional.'),
('Educação das Relações Étnico-Raciais','Práticas pedagógicas e equidade racial',10,'Revise descrevendo uma prática que poderia ampliar equidade racial em uma turma. Indique a barreira enfrentada, a ação proposta e qual evidência mostraria resultado.'),
('Educação, Diversidade e Direitos Humanos','Direitos humanos e educação',1,'Educação em direitos humanos trabalha conhecimentos, valores e práticas relacionados à dignidade, igualdade, liberdade, participação e respeito. Na escola, não se limita a memorizar documentos: envolve formas concretas de convivência e análise de situações sociais.'),
('Educação, Diversidade e Direitos Humanos','Direitos humanos e educação',2,'Direitos humanos são universais, mas sua efetivação depende de contextos históricos e institucionais. A escola pode criar oportunidades para conhecer direitos, reconhecer violações e desenvolver formas responsáveis de participação.'),
('Educação, Diversidade e Direitos Humanos','Direitos humanos e educação',3,'O pedagogo contribui para integrar direitos humanos ao currículo, à gestão e às relações. Isso requer coerência entre o que a escola ensina sobre respeito e as experiências que oferece aos estudantes.'),
('Educação, Diversidade e Direitos Humanos','Direitos humanos e educação',4,'Uma turma pode analisar uma situação de discriminação, identificar quais direitos estão envolvidos e discutir formas de intervenção. A atividade articula conhecimento conceitual e prática de participação.'),
('Educação, Diversidade e Direitos Humanos','Direitos humanos e educação',5,'Ao planejar uma atividade, pergunte qual direito ou princípio será estudado, quais fontes sustentam a discussão e como os estudantes poderão argumentar sem transformar o debate em disputa pessoal.'),
('Educação, Diversidade e Direitos Humanos','Direitos humanos e educação',6,'Um erro comum é tratar direitos humanos como opinião individual. O estudo precisa distinguir princípios normativos, documentos e interpretações, permitindo discussão crítica com base em fontes.'),
('Educação, Diversidade e Direitos Humanos','Direitos humanos e educação',7,'As Diretrizes Nacionais para a Educação em Direitos Humanos orientam a presença do tema na educação e reforçam sua relação com dignidade, igualdade, participação e cultura de direitos.'),
('Educação, Diversidade e Direitos Humanos','Direitos humanos e educação',8,'Na prática, use casos, documentos e situações escolares para transformar princípios abstratos em problemas analisáveis. Depois avalie a qualidade da argumentação, o uso de evidências e o respeito às regras de diálogo.'),
('Educação, Diversidade e Direitos Humanos','Direitos humanos e educação',9,'Educação em direitos humanos une conhecimento e prática. A escola ensina direitos também pela maneira como organiza participação, conflitos, regras e reconhecimento dos estudantes.'),
('Educação, Diversidade e Direitos Humanos','Direitos humanos e educação',10,'Revise escolhendo um direito humano e explicando como ele poderia aparecer em uma atividade curricular e em uma prática de convivência escolar.'),
('Educação, Diversidade e Direitos Humanos','Diversidade e diferenças',1,'Diversidade se refere à existência de diferentes experiências, identidades, culturas, corpos, trajetórias e modos de participar da vida social. Diferença não é sinônimo de desigualdade: desigualdades aparecem quando diferenças são associadas a tratamento injusto ou acesso desigual a direitos e oportunidades.'),
('Educação, Diversidade e Direitos Humanos','Diversidade e diferenças',2,'Na escola, reconhecer diversidade exige evitar tanto a homogeneização quanto a criação de grupos vistos apenas por suas diferenças. O trabalho pedagógico precisa preservar singularidades e, ao mesmo tempo, construir experiências comuns de aprendizagem.'),
('Educação, Diversidade e Direitos Humanos','Diversidade e diferenças',3,'O pedagogo pode analisar materiais, exemplos e regras para verificar se determinados grupos são invisibilizados ou estereotipados. Também deve observar se as diferenças são respeitadas nas formas de participação e avaliação.'),
('Educação, Diversidade e Direitos Humanos','Diversidade e diferenças',4,'Uma atividade que permite diferentes exemplos e experiências dos estudantes pode enriquecer o conteúdo. O professor precisa, porém, evitar transformar um estudante em porta-voz obrigatório de um grupo social.'),
('Educação, Diversidade e Direitos Humanos','Diversidade e diferenças',5,'Ao planejar, identifique quais diferenças estão presentes e quais delas podem criar barreiras de acesso. Depois escolha estratégias que ampliem participação sem presumir características individuais.'),
('Educação, Diversidade e Direitos Humanos','Diversidade e diferenças',6,'Um erro comum é afirmar que “somos todos iguais” para evitar falar sobre desigualdade. Igualdade de dignidade e direitos não exige apagar diferenças sociais, culturais ou históricas.'),
('Educação, Diversidade e Direitos Humanos','Diversidade e diferenças',7,'A Educação em Direitos Humanos enfatiza igualdade e não discriminação. Na escola, esse princípio precisa orientar currículo, convivência e acesso às oportunidades de aprendizagem.'),
('Educação, Diversidade e Direitos Humanos','Diversidade e diferenças',8,'Na prática, utilize linguagem respeitosa, exemplos variados e regras de participação claras. Monitore quem está conseguindo falar, produzir e aprender e ajuste a organização quando necessário.'),
('Educação, Diversidade e Direitos Humanos','Diversidade e diferenças',9,'Trabalhar diversidade significa reconhecer pluralidade e combater situações em que diferenças são usadas para hierarquizar pessoas. A educação precisa combinar reconhecimento, conhecimento e equidade.'),
('Educação, Diversidade e Direitos Humanos','Diversidade e diferenças',10,'Revise explicando a diferença entre diversidade e desigualdade. Depois analise uma regra escolar e diga se ela pode produzir barreira ou tratamento desigual.'),
('Educação, Diversidade e Direitos Humanos','Gênero, respeito e convivência',1,'O trabalho pedagógico sobre gênero pode abordar expectativas sociais, respeito, convivência e situações de discriminação. O foco educacional deve ser análise crítica e promoção de relações respeitosas, considerando as normas e o contexto da etapa de ensino.'),
('Educação, Diversidade e Direitos Humanos','Gênero, respeito e convivência',2,'Papéis de gênero são influenciados por contextos culturais e históricos. A escola pode problematizar estereótipos que limitam participação ou criam expectativas diferentes para grupos de estudantes.'),
('Educação, Diversidade e Direitos Humanos','Gênero, respeito e convivência',3,'Para o pedagogo, o tema aparece em linguagem, distribuição de tarefas, brincadeiras, expectativas sobre desempenho e respostas a situações de violência ou discriminação. Observar o cotidiano é parte da intervenção.'),
('Educação, Diversidade e Direitos Humanos','Gênero, respeito e convivência',4,'Em uma atividade, perceba se meninos e meninas estão recebendo oportunidades semelhantes para liderança, uso de materiais e escolha de temas. A observação pode revelar padrões que uma regra formal não mostra.'),
('Educação, Diversidade e Direitos Humanos','Gênero, respeito e convivência',5,'Ao tratar gênero, estabeleça conceitos, fontes e regras de diálogo. Diferencie opinião, argumento e evidência para que a discussão permaneça educativa e respeitosa.'),
('Educação, Diversidade e Direitos Humanos','Gênero, respeito e convivência',6,'Um erro comum é transformar o tema em disputa moral entre estudantes. O trabalho pedagógico precisa criar condições para analisar situações e princípios, combater discriminação e respeitar a legislação educacional aplicável.'),
('Educação, Diversidade e Direitos Humanos','Gênero, respeito e convivência',7,'A educação em direitos humanos fundamenta práticas escolares de respeito e não discriminação. A forma concreta de abordar questões de gênero deve considerar faixa etária, currículo e normas da rede de ensino.'),
('Educação, Diversidade e Direitos Humanos','Gênero, respeito e convivência',8,'Em conflitos, o pedagogo pode separar os fatos das interpretações, garantir escuta, aplicar regras institucionais e criar ações preventivas de convivência. O registro deve preservar a dignidade dos envolvidos.'),
('Educação, Diversidade e Direitos Humanos','Gênero, respeito e convivência',9,'Respeito e convivência são aprendidos em práticas concretas. A escola ensina também por como distribui atenção, estabelece limites e reage a discriminações.'),
('Educação, Diversidade e Direitos Humanos','Gênero, respeito e convivência',10,'Revise identificando duas formas pelas quais expectativas de gênero podem aparecer no cotidiano escolar. Depois proponha uma intervenção pedagógica baseada em respeito e evidências.'),
('Educação, Diversidade e Direitos Humanos','Democracia e participação',1,'Democracia, na educação, envolve participação, diálogo, regras legítimas e capacidade de argumentar e tomar decisões coletivas. A escola pode ensinar democracia tanto por conteúdos curriculares quanto pelas formas de organizar sua vida cotidiana.'),
('Educação, Diversidade e Direitos Humanos','Democracia e participação',2,'Participação não significa que toda decisão será tomada por todos. Significa criar espaços e procedimentos nos quais estudantes possam expressar razões, ouvir posições e exercer responsabilidades compatíveis com sua etapa de formação.'),
('Educação, Diversidade e Direitos Humanos','Democracia e participação',3,'O pedagogo pode organizar assembleias, projetos coletivos e processos de decisão com objetivos pedagógicos claros. A participação precisa ser ensinada: regras, argumentação, escuta e responsabilidade são competências construídas.'),
('Educação, Diversidade e Direitos Humanos','Democracia e participação',4,'Uma turma pode decidir coletivamente critérios para organizar um projeto, registrar propostas, discutir justificativas e avaliar o resultado. A experiência torna visível a relação entre participação e responsabilidade.'),
('Educação, Diversidade e Direitos Humanos','Democracia e participação',5,'Ao planejar uma atividade participativa, defina quem decide, sobre o quê, com quais informações, em qual prazo e como a decisão será registrada. Isso evita participação apenas simbólica.'),
('Educação, Diversidade e Direitos Humanos','Democracia e participação',6,'Um erro comum é confundir democracia com ausência de regras. Participação democrática depende de regras que protejam fala, escuta, integridade e direitos de todos.'),
('Educação, Diversidade e Direitos Humanos','Democracia e participação',7,'As diretrizes de Educação em Direitos Humanos relacionam participação e cidadania. Na escola, isso pode ser desenvolvido por práticas de diálogo, respeito, responsabilidade e análise crítica de problemas sociais.'),
('Educação, Diversidade e Direitos Humanos','Democracia e participação',8,'Na prática, avalie a qualidade da participação: variedade de vozes, uso de argumentos, escuta das diferenças e capacidade de revisar posições diante de evidências.'),
('Educação, Diversidade e Direitos Humanos','Democracia e participação',9,'Participação democrática é uma prática educativa. Ela combina liberdade de expressão com responsabilidade, direitos com deveres e decisões coletivas com critérios e limites.'),
('Educação, Diversidade e Direitos Humanos','Democracia e participação',10,'Revise explicando a diferença entre participação simbólica e participação efetiva. Depois desenhe uma atividade em que estudantes tenham uma decisão real, porém adequada ao contexto escolar.'),
('Educação, Diversidade e Direitos Humanos','Práticas educativas para a equidade',1,'Práticas educativas para a equidade procuram identificar desigualdades de acesso, participação e aprendizagem e criar respostas pedagógicas justificadas. Equidade não é privilégio: é considerar condições diferentes para garantir oportunidades educacionais efetivas.'),
('Educação, Diversidade e Direitos Humanos','Práticas educativas para a equidade',2,'Uma prática equitativa começa pela identificação de barreiras. O professor precisa saber quem está tendo dificuldade, em qual situação e com quais recursos, para evitar decisões baseadas apenas em impressões.'),
('Educação, Diversidade e Direitos Humanos','Práticas educativas para a equidade',3,'Na Pedagogia, equidade se articula ao currículo, à avaliação e à gestão da escola. O pedagogo pode analisar dados de participação, frequência e aprendizagem, combinando-os com observações qualitativas para orientar ações.'),
('Educação, Diversidade e Direitos Humanos','Práticas educativas para a equidade',4,'Se determinado grupo participa menos de projetos de liderança, a escola pode investigar as causas, revisar regras de seleção e criar oportunidades mais acessíveis. O objetivo é remover barreiras, não distribuir papéis por estereótipos.'),
('Educação, Diversidade e Direitos Humanos','Práticas educativas para a equidade',5,'Ao acompanhar uma ação, defina indicador, período e evidência. Por exemplo: participação em atividades, acesso a materiais, entrega de produções ou percepção de segurança para falar.'),
('Educação, Diversidade e Direitos Humanos','Práticas educativas para a equidade',6,'Um erro comum é aplicar exatamente a mesma intervenção a situações diferentes porque “tratar todos igual” parece neutro. A equidade exige olhar para desigualdades concretas e escolher respostas proporcionais e justificáveis.'),
('Educação, Diversidade e Direitos Humanos','Práticas educativas para a equidade',7,'As políticas de direitos humanos e diversidade orientam ações de não discriminação e participação. A implementação deve considerar legislação, projeto pedagógico, características do público e recursos da rede.'),
('Educação, Diversidade e Direitos Humanos','Práticas educativas para a equidade',8,'Na prática, combine medidas universais com apoios direcionados quando necessários. Depois verifique se a intervenção ampliou participação e aprendizagem sem criar novos estigmas.'),
('Educação, Diversidade e Direitos Humanos','Práticas educativas para a equidade',9,'Equidade é um processo de ajuste contínuo baseado em evidências. O pedagogo precisa acompanhar resultados, revisar estratégias e manter foco no direito de todos à educação e à dignidade.'),
('Educação, Diversidade e Direitos Humanos','Práticas educativas para a equidade',10,'Revise escolhendo uma desigualdade educacional e construindo uma resposta em quatro passos: evidência, barreira, ação e indicador de resultado. Explique por que a ação é equitativa.')
)
update public.material_sections s
set content=v.content, updated_at=now()
from v, public.materials m, public.topics t, public.disciplines d, public.courses c
where s.material_id=m.id and m.topic_id=t.id and t.discipline_id=d.id and d.course_id=c.id
  and c.slug='pedagogia' and d.name=v.discipline and t.name=v.topic and s.position=v.position;